        box.E22 = Settings.ParticleBoxSpan.Y;
        box.E33 = Settings.ParticleBoxSpan.Z;
        box.E12 = 0; box.E13 = 0; box.E21 = 0; box.E23 = 0; box.E31 = 0; box.E32 = 0;
        box.E41 = pos.X; box.E42 = pos.Y; box.E43 = pos.Z;
